INSERT INTO public.american_lessons (id,book_no,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question,grammar_card) VALUES ('am2_l57',2,8,57,'Can I help you?','有什么需要帮忙的吗?','KS9+KS33 介词 at/in/off/with 综合复习(at 某一点、in 之内/穿着、off 离开脱落、with 带有拿着)(教材 L57 Key structures)主考;SD make/let sb do(不带 to 不定式)+ 课文 the way + 从句、into、be eager to do(辅考)。素材=Aaron 净化生产包(2026-07-05,原课文过滤误判已核无害);unit_no=8(课程 U8 首课,L57-64)','一个穿牛仔裤的女人站在一家高档商店的橱窗前,看着一条连衣裙。她犹豫了一下,然后走进去要求看看。店员不喜欢她的穿着,轻蔑地瞥了她一眼,说那条裙子卖掉了。女人气冲冲地走了,决定第二天惩罚他。第二天早上她穿着皮草大衣回来,一手拿着钱包,一手拿着长伞。这次店员没认出她,急切地想为她服务。他爬进橱窗,把裙子从展台上取下来。她一看见就说不喜欢。她让店员把橱窗里几乎所有东西一件接一件都拿来。然后,她微笑着,最终买下了她第一次要看的那条裙子。','{"q":"Listen and answer — Did the woman get what she wanted?","options":["Yes — after teasing the clerk, she bought the very dress she first asked for","No, the dress was really sold","No, she left with nothing","She bought a fur coat instead"],"answer_index":0}'::jsonb,'{"title":"介词 at / in / off / with","intro":"KS9+KS33 综合复习介词:at 表''在某一点''(at the window、at the door、glance at);in 表''在…之内''或''穿着''(in jeans、in a fur coat、in the store);off 表''离开、脱落''(walk off、take off、off the shelf);with 表''带有、拿着''(with a purse、with a smile)。","table":{"headers":["介词","例子"],"rows":[["at 某一点","at the window / glanced at her"],["in 之内/穿着","a woman in jeans / in a fur coat"],["off 离开/脱落","walked off / take the dress off"],["with 带有/拿着","with a purse in one hand"]]},"specialRules":[{"rule":"SD Make and Let:make sb do、let sb do 后接不带 to 的动词原形(made the clerk bring、let her try)。","mark":"make/let sb do"},{"rule":"the way + 从句表''…的方式''(the way she was dressed = 她穿着打扮的样子);介词 into 表''进入…里面''(climbed into the window)。","mark":"the way / into"}]}'::jsonb) ON CONFLICT (id) DO UPDATE SET book_no=EXCLUDED.book_no,title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question,grammar_card=EXCLUDED.grammar_card;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l57',1,NULL,'A woman in jeans stood at the window of an expensive store, looking at a dress.','一个穿牛仔裤的女人站在一家高档商店的橱窗前,看着一条连衣裙。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l57',2,NULL,'She hesitated for a moment, then walked in and asked to see it.','她犹豫了一下,然后走进去要求看看。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l57',3,NULL,'The salesclerk didn''t like the way she was dressed. Glancing at her scornfully, he said the dress was sold.','店员不喜欢她的穿着,轻蔑地瞥了她一眼,说那条裙子卖掉了。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l57',4,NULL,'The woman walked off angrily and decided to punish him the next day.','女人气冲冲地走了,决定第二天惩罚他。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l57',5,NULL,'The next morning she came back in a fur coat, with a purse in one hand and a long umbrella in the other.','第二天早上她穿着皮草大衣回来,一手拿着钱包,一手拿着长伞。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l57',6,NULL,'This time the clerk didn''t recognize her and was eager to serve her.','这次店员没认出她,急切地想为她服务。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l57',7,NULL,'He climbed into the window to take the dress off the display. As soon as she saw it, she said she didn''t like it.','他爬进橱窗,把裙子从展台上取下来。她一看见就说不喜欢。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l57',8,NULL,'She made the clerk bring almost everything in the window, one thing after another. Then, with a smile, she finally bought the very dress she had asked for the first time.','她让店员把橱窗里几乎所有东西一件接一件都拿来。然后,她微笑着,最终买下了她第一次要看的那条裙子。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
