INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn) VALUES ('am2_l57','store','shop','商店;美语 store,英式 shop') ON CONFLICT (lesson_id,us) DO UPDATE SET uk=EXCLUDED.uk,note_cn=EXCLUDED.note_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn) VALUES ('am2_l57','purse','handbag','(女式)手提包;美语 purse,英式 handbag') ON CONFLICT (lesson_id,us) DO UPDATE SET uk=EXCLUDED.uk,note_cn=EXCLUDED.note_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn) VALUES ('am2_l57','salesclerk','shop assistant','店员;美语 salesclerk / store clerk,英式 shop assistant') ON CONFLICT (lesson_id,us) DO UPDATE SET uk=EXCLUDED.uk,note_cn=EXCLUDED.note_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn) VALUES ('am2_l57','pants','trousers','裤子;美语 pants,英式 trousers') ON CONFLICT (lesson_id,us) DO UPDATE SET uk=EXCLUDED.uk,note_cn=EXCLUDED.note_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l57','make sb do','',NULL,'/meɪk ... duː/','She made the clerk bring everything.','她让店员把东西全拿来。','You can''t make me change my mind.','你没法让我改主意。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l57','the way (she was dressed)','',NULL,'/ðə weɪ/','He didn''t like the way she was dressed.','他不喜欢她的穿着打扮。','I like the way you sing.','我喜欢你唱歌的样子。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l57','be eager to do','',NULL,'/ˈiːɡər tuː duː/','He was eager to serve her.','他急切地想为她服务。','She''s eager to learn.','她渴望学习。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l57','try on','',NULL,'/traɪ ɑːn/','She wanted to try on the dress.','她想试穿那条裙子。','Can I try these pants on?','我能试穿这条裤子吗?') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l57',5,'am2_l57_gp1','choice','{"stem":"\"She stood ___ the window of an expensive store.\"(在橱窗''前''·某一点)","options":["with","in","at","off"],"answer_index":2,"stem_cn":"她站在一家高档商店的橱窗前。","explanation_cn":"表示\"在某一点\"(橱窗前)用 at。✓ She stood at the window of an expensive store. ✗ in:表在…之内;✗ off:表离开、脱落;✗ with:表带有。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l57',5,'am2_l57_gp1','choice','{"stem":"\"He glanced ___ her scornfully.\"(朝某人''看''·某一点)","options":["off","in","with","at"],"answer_index":3,"stem_cn":"他轻蔑地瞥了她一眼。","explanation_cn":"\"朝某人看\"用 glance at,at 表某一点/目标。✓ He glanced at her scornfully. ✗ in:表在…之内;✗ off:表离开;✗ with:表带有。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l57',5,'am2_l57_gp1','choice','{"stem":"\"Someone is knocking ___ the door.\"(在门口·某一点)","options":["at","with","in","off"],"answer_index":0,"stem_cn":"有人在敲门。","explanation_cn":"\"敲门\"用 knock at the door,at 表某一点(门口)。✓ Someone is knocking at the door. ✗ in:表在…之内;✗ off:表离开;✗ with:表带有。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l57',5,'am2_l57_gp2','choice','{"stem":"\"A woman ___ jeans stood at the window.\"(表''穿着''牛仔裤)","options":["off","in","at","with"],"answer_index":1,"stem_cn":"一个穿牛仔裤的女人站在橱窗前。","explanation_cn":"表示\"穿着\"(牛仔裤)用 in。✓ A woman in jeans stood at the window. ✗ at:表某一点;✗ off:表离开;✗ with:表带有。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l57',5,'am2_l57_gp2','choice','{"stem":"\"The next morning she came back ___ a fur coat.\"(表''穿着''皮草大衣)","options":["in","at","off","on"],"answer_index":0,"stem_cn":"第二天早上她穿着皮草大衣回来。","explanation_cn":"表示\"穿着\"(皮草大衣)用 in。✓ She came back in a fur coat. ✗ at:表某一点;✗ off:表脱落;✗ on:此处\"穿着…这身\"用 in 更自然。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l57',5,'am2_l57_gp2','choice','{"stem":"\"There were a lot of people ___ the store.\"(在商店''里''·之内)","options":["at","in","with","off"],"answer_index":1,"stem_cn":"店里有很多人。","explanation_cn":"表示\"在…之内\"(店里)用 in。✓ There were a lot of people in the store. ✗ at:表某一点;✗ off:表离开;✗ with:表带有。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l57',5,'am2_l57_gp2','choice','{"stem":"\"Can you see that woman ___ the blue coat?\"(表''穿着''蓝外套)","options":["with","at","in","off"],"answer_index":2,"stem_cn":"你能看见那个穿蓝外套的女士吗?","explanation_cn":"表示\"穿着\"(蓝外套)用 in。✓ Can you see that woman in the blue coat? ✗ at:表某一点;✗ with:此处描述\"穿着\"用 in;✗ off:表脱落。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l57',5,'am2_l57_gp3','choice','{"stem":"\"The woman walked ___ angrily.\"(生气地''走开、离去'')","options":["in","with","at","off"],"answer_index":3,"stem_cn":"女人气冲冲地走开了。","explanation_cn":"表示\"离开、走开\"用 walk off,off 表离去。✓ The woman walked off angrily. ✗ in:表在…之内;✗ at:表某一点;✗ with:表带有。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l57',5,'am2_l57_gp3','choice','{"stem":"\"He took the dress ___ the display.\"(从展台上''取下来'')","options":["off","with","at","in"],"answer_index":0,"stem_cn":"他把裙子从展台上取下来。","explanation_cn":"表示\"从…上取下、脱离\"用 take ... off,off 表脱落。✓ He took the dress off the display. ✗ in:表在…之内;✗ at:表某一点;✗ with:表带有。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l57',5,'am2_l57_gp3','choice','{"stem":"\"Take your coat ___.\"(把外套''脱下来'')","options":["at","out","in","off"],"answer_index":3,"stem_cn":"把你的外套脱下来。","explanation_cn":"表示\"脱下(衣物)\"用 take ... off。✓ Take your coat off. ✗ in:表穿上;✗ at:表某一点;✗ out:take out 是\"取出\",此处脱衣用 off。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l57',5,'am2_l57_gp4','choice','{"stem":"\"She came back ___ a purse in one hand and an umbrella in the other.\"(表''带着、拿着''钱包)","options":["off","with","in","at"],"answer_index":1,"stem_cn":"她一手拿着钱包,一手拿着伞回来了。","explanation_cn":"表示\"带着、拿着\"(钱包)用 with。✓ She came back with a purse in one hand. ✗ in:表穿着/在…之内;✗ at:表某一点;✗ off:表离开。"}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l57',5,'am2_l57_gp4','choice','{"stem":"\"The police are looking for a man ___ a scar on his face.\"(表''带有''脸上伤疤这个特征)","options":["in","at","off","with"],"answer_index":3,"stem_cn":"警察在找一个脸上有疤的男人。","explanation_cn":"表示\"带有…特征\"(脸上有疤)用 with。✓ a man with a scar on his face. ✗ in:表穿着;✗ at:表某一点;✗ off:表离开。"}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l57',5,'am2_l57_gp4','choice','{"stem":"\"Then, ___ a smile, she bought the dress.\"(表''带着''微笑)","options":["with","at","in","off"],"answer_index":0,"stem_cn":"然后她微笑着买下了那条裙子。","explanation_cn":"表示\"带着\"(微笑)用 with。✓ Then, with a smile, she bought the dress. ✗ in:表穿着/之内;✗ at:表某一点;✗ off:表离开。"}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l57',5,'am2_l57_gp5','choice','{"stem":"\"She made the clerk ___ almost everything in the window.\"(make 后接不带 to 的动词原形)","options":["brought","bringing","bring","to bring"],"answer_index":2,"stem_cn":"她让店员把橱窗里几乎所有东西都拿来。","explanation_cn":"make sb do sth,make 后接不带 to 的动词原形。✓ She made the clerk bring almost everything. ✗ to bring:make 后不带 to;✗ bringing:不用现在分词;✗ brought:不用过去式。"}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l57',5,'am2_l57_gp5','choice','{"stem":"\"You can''t make me ___ my mind.\"(make 后接不带 to 的动词原形)","options":["to change","change","changed","changing"],"answer_index":1,"stem_cn":"你没法让我改变主意。","explanation_cn":"make sb do sth,make 后接不带 to 的动词原形。✓ You can''t make me change my mind. ✗ to change:make 后不带 to;✗ changing:不用现在分词;✗ changed:不用过去式。"}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l57',5,'am2_l57_gp5','choice','{"stem":"\"He wouldn''t let her ___ on the dress.\"(let 后接不带 to 的动词原形)","options":["to try","tried","trying","try"],"answer_index":3,"stem_cn":"他不肯让她试穿那条裙子。","explanation_cn":"let sb do sth,let 后接不带 to 的动词原形。✓ He wouldn''t let her try on the dress. ✗ to try:let 后不带 to;✗ trying:不用现在分词;✗ tried:不用过去式。"}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l57',5,'am2_l57_gp6','choice','{"stem":"\"The salesclerk didn''t like the way she ___ dressed.\"(她''当时''被打扮成…的样子,用过去的 be 动词)","options":["is","was","being","has"],"answer_index":1,"stem_cn":"店员不喜欢她的穿着打扮。","explanation_cn":"the way + 从句,描述\"她当时穿着打扮的样子\",从句主语 she 用过去的 be 动词 was。✓ the way she was dressed. ✗ is:时态应是过去;✗ has:构不成被动;✗ being:缺少限定动词。"}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l57',5,'am2_l57_gp6','choice','{"stem":"\"He climbed ___ the window to get the dress.\"(爬''进…里面''的介词)","options":["off","for","at","into"],"answer_index":3,"stem_cn":"他爬进橱窗去取裙子。","explanation_cn":"表示\"进入…里面\"用 into(动作+方向)。✓ He climbed into the window to get the dress. ✗ at:表某一点;✗ off:表离开;✗ for:表目的/为了。"}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l57',6,NULL,'choice','{"stem":"美语里\"商店\"常说:","options":["sale house","store","market place","shop"],"answer_index":1,"explanation_cn":"美语\"商店\"常说 store;英式说 shop。✓ an expensive store 一家高档商店。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l57',6,NULL,'choice','{"stem":"美语里\"(女式)手提包\"常说:","options":["carry bag","hand sack","purse","handbag"],"answer_index":2,"explanation_cn":"美语\"(女式)手提包\"常说 purse;英式说 handbag。✓ with a purse in one hand 一手拿着手提包。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l57',6,NULL,'choice','{"stem":"hesitate 的意思是:","options":["答应","匆忙","决定","犹豫,迟疑"],"answer_index":3,"explanation_cn":"hesitate = 犹豫、迟疑。✓ She hesitated for a moment 她犹豫了一下。\n顺带记:决定 = decide;匆忙 = hurry;答应 = agree."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l57',6,NULL,'choice','{"stem":"scornfully 的意思是:","options":["轻蔑地","小心地","热情地","礼貌地"],"answer_index":0,"explanation_cn":"scornfully = 轻蔑地。✓ Glancing at her scornfully 轻蔑地瞥她一眼。\n顺带记:热情地 = warmly;礼貌地 = politely;小心地 = carefully."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l57',6,NULL,'choice','{"stem":"eager 的意思是:","options":["疲倦的","急切的,渴望的","冷淡的","害怕的"],"answer_index":1,"explanation_cn":"eager = 急切的、渴望的。✓ was eager to serve her 急切地想为她服务。\n顺带记:冷淡的 = cold;疲倦的 = tired;害怕的 = afraid."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l57',6,NULL,'choice','{"stem":"punish 的意思是:","options":["原谅","奖励","惩罚","邀请"],"answer_index":2,"explanation_cn":"punish = 惩罚。✓ decided to punish him 决定惩罚他。\n顺带记:奖励 = reward;原谅 = forgive;邀请 = invite."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l57',7,NULL,'cloze','{"stem":"第 1 空","context":"A woman ___1___ jeans stood ___2___ the window of an expensive store. The salesclerk glanced ___3___ her scornfully and said the dress was sold. The next day she came back ___4___ a fur coat to punish him.","blank_no":1,"options":["in","at","off","with"],"answer_index":0,"explanation_cn":"表示\"穿着\"(牛仔裤)用 in。✓ A woman in jeans stood at the window.\n✗ at:表某一点;✗ off:表离开;✗ with:表带有。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l57',7,NULL,'cloze','{"stem":"第 2 空","context":"A woman ___1___ jeans stood ___2___ the window of an expensive store. The salesclerk glanced ___3___ her scornfully and said the dress was sold. The next day she came back ___4___ a fur coat to punish him.","blank_no":2,"options":["at","in","off","with"],"answer_index":0,"explanation_cn":"表示\"在某一点\"(橱窗前)用 at。✓ stood at the window of an expensive store.\n✗ in:表在…之内;✗ off:表离开;✗ with:表带有。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l57',7,NULL,'cloze','{"stem":"第 3 空","context":"A woman ___1___ jeans stood ___2___ the window of an expensive store. The salesclerk glanced ___3___ her scornfully and said the dress was sold. The next day she came back ___4___ a fur coat to punish him.","blank_no":3,"options":["at","in","off","with"],"answer_index":0,"explanation_cn":"\"朝某人看\"用 glance at,at 表目标/某一点。✓ The salesclerk glanced at her scornfully.\n✗ in:表在…之内;✗ off:表离开;✗ with:表带有。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l57',7,NULL,'cloze','{"stem":"第 4 空","context":"A woman ___1___ jeans stood ___2___ the window of an expensive store. The salesclerk glanced ___3___ her scornfully and said the dress was sold. The next day she came back ___4___ a fur coat to punish him.","blank_no":4,"options":["in","at","off","with"],"answer_index":0,"explanation_cn":"表示\"穿着\"(皮草大衣)用 in。✓ she came back in a fur coat.\n✗ at:表某一点;✗ off:表脱落;✗ with:此处\"穿着这身\"用 in。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l57',8,NULL,'choice','{"stem":"Why did the salesclerk say the dress was sold?","options":["It really was sold","She had no money","He looked down on the woman because she was dressed in jeans","The store was closing"],"answer_index":2,"explanation_cn":"课文说 The salesclerk didn''t like the way she was dressed,穿牛仔裤被看不起,才谎称裙子卖了。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l57',8,NULL,'choice','{"stem":"How did the woman look when she returned the next day?","options":["In a raincoat","In the same jeans","In a school uniform","In a fur coat, with a purse and a long umbrella"],"answer_index":3,"explanation_cn":"课文说 she came back in a fur coat, with a purse in one hand and a long umbrella in the other。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l57',8,NULL,'choice','{"stem":"What did the woman finally buy?","options":["The very dress she had first asked to see","Nothing at all","A fur coat","An umbrella"],"answer_index":0,"explanation_cn":"课文说 she finally bought the very dress she had asked for the first time。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l57',9,NULL,'choice','{"stem":"你想说\"你没法让我改变主意\"(make sb do,后接不带 to 的动词):","options":["You can''t make me change my mind.","You can''t make me to change my mind.","You can''t make me changed my mind.","You can''t make me changing my mind."],"answer_index":0,"explanation_cn":"make sb do sth,make 后接不带 to 的动词原形(change,不是 to change)。✓ You can''t make me change my mind. 场合:说\"你没法逼我做某事\"。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l57',9,NULL,'choice','{"stem":"你想说\"你能看见那个穿蓝外套的女士吗?\"(表''穿着''用 in):","options":["Can you see that woman with the blue coat?","Can you see that woman in the blue coat?","Can you see that woman at the blue coat?","Can you see that woman on the blue coat?"],"answer_index":1,"explanation_cn":"表示\"穿着\"某件衣服用 in(in the blue coat)。✓ Can you see that woman in the blue coat? 场合:用穿着来指认某人。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l57',9,NULL,'choice','{"stem":"你想说\"她一手拿着钱包回来了\"(表''带着、拿着''用 with):","options":["She came back off a purse in one hand.","She came back at a purse in one hand.","She came back in a purse in one hand.","She came back with a purse in one hand."],"answer_index":3,"explanation_cn":"表示\"带着、拿着\"某物用 with。✓ She came back with a purse in one hand. 场合:描述某人手里拿着东西。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l57',10,NULL,'choice','{"stem":"hesitate 的意思是:","options":["决定","匆忙","犹豫,迟疑","答应"],"answer_index":2,"explanation_cn":"hesitate = 犹豫、迟疑。✓ She hesitated for a moment 她犹豫了一下。\n顺带记:决定 = decide;匆忙 = hurry;答应 = agree."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l57',10,NULL,'choice','{"stem":"eager 的意思是:","options":["害怕的","疲倦的","冷淡的","急切的,渴望的"],"answer_index":3,"explanation_cn":"eager = 急切的、渴望的。✓ was eager to serve her 急切地想为她服务。\n顺带记:冷淡的 = cold;疲倦的 = tired;害怕的 = afraid."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l57',10,NULL,'choice','{"stem":"\"She glanced ___ him scornfully.\"(某一点用哪个介词)","options":["at","in","with","off"],"answer_index":0,"stem_cn":"她轻蔑地瞥了他一眼。","explanation_cn":"表示\"在某一点/朝目标\"用 at(glance at)。✓ She glanced at him scornfully.\n✗ in:表在…之内;✗ off:表离开;✗ with:表带有。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l57',10,NULL,'choice','{"stem":"\"She made the clerk ___ everything.\"(make sb 后接的动词形式)","options":["brought","bringing","bring","to bring"],"answer_index":2,"stem_cn":"她让店员把东西全拿来。","explanation_cn":"make sb do sth,make 后接不带 to 的动词原形。✓ She made the clerk bring everything.\n✗ to bring:make 后不带 to;✗ bringing:不用现在分词;✗ brought:不用过去式。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l57',10,NULL,'choice','{"stem":"\"walk off angrily\" 的意思是:","options":["站着不动","慢慢地散步","开心地跑开","生气地走开"],"answer_index":3,"explanation_cn":"walk off angrily = 生气地走开、气冲冲地离去(off 表离开)。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l57',10,NULL,'choice','{"stem":"\"make sb do\" 结构的意思是:","options":["让/使某人做某事","帮某人做某事","看某人做某事","为某人做某事"],"answer_index":0,"explanation_cn":"make sb do = 让/使某人做某事(后接不带 to 的动词原形)。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l57',10,NULL,'choice','{"stem":"Why did the woman come back in a fur coat the next day?","options":["Because it was cold","To punish the salesclerk who had looked down on her","To return the coat","To attend a party"],"answer_index":1,"passage":"A woman in jeans stood at the window of an expensive store, looking at a dress. She hesitated for a moment, then walked in and asked to see it. The salesclerk didn''t like the way she was dressed. Glancing at her scornfully, he said the dress was sold. The woman walked off angrily and decided to punish him the next day. The next morning she came back in a fur coat, with a purse in one hand and a long umbrella in the other. This time the clerk didn''t recognize her and was eager to serve her. He climbed into the window to take the dress off the display. As soon as she saw it, she said she didn''t like it. She made the clerk bring almost everything in the window, one thing after another. Then, with a smile, she finally bought the very dress she had asked for the first time.","explanation_cn":"课文说 she decided to punish him,穿皮草回来是为了报复那个势利的店员。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l57',10,NULL,'choice','{"stem":"What did she make the salesclerk do?","options":["Call the manager","Apologize to her","Bring almost everything in the window, one thing after another","Gift-wrap the dress"],"answer_index":2,"passage":"A woman in jeans stood at the window of an expensive store, looking at a dress. She hesitated for a moment, then walked in and asked to see it. The salesclerk didn''t like the way she was dressed. Glancing at her scornfully, he said the dress was sold. The woman walked off angrily and decided to punish him the next day. The next morning she came back in a fur coat, with a purse in one hand and a long umbrella in the other. This time the clerk didn''t recognize her and was eager to serve her. He climbed into the window to take the dress off the display. As soon as she saw it, she said she didn''t like it. She made the clerk bring almost everything in the window, one thing after another. Then, with a smile, she finally bought the very dress she had asked for the first time.","explanation_cn":"课文说 She made the clerk bring almost everything in the window, one thing after another。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l57',10,NULL,'choice','{"stem":"What was the woman wearing the first time?","options":["A blue coat","A fur coat","A uniform","Jeans"],"answer_index":3,"audio":"A woman in jeans stood at the window of an expensive store, looking at a dress. She hesitated for a moment, then walked in and asked to see it. The salesclerk didn''t like the way she was dressed. Glancing at her scornfully, he said the dress was sold. The woman walked off angrily and decided to punish him the next day. The next morning she came back in a fur coat, with a purse in one hand and a long umbrella in the other. This time the clerk didn''t recognize her and was eager to serve her. He climbed into the window to take the dress off the display. As soon as she saw it, she said she didn''t like it. She made the clerk bring almost everything in the window, one thing after another. Then, with a smile, she finally bought the very dress she had asked for the first time.","explanation_cn":"课文说 A woman in jeans stood at the window,第一次她穿着牛仔裤。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l57',10,NULL,'choice','{"stem":"Why was the clerk eager to serve her the second time?","options":["The manager told him to","She offered him a tip","He didn''t recognize her","She was a famous actress"],"answer_index":2,"audio":"A woman in jeans stood at the window of an expensive store, looking at a dress. She hesitated for a moment, then walked in and asked to see it. The salesclerk didn''t like the way she was dressed. Glancing at her scornfully, he said the dress was sold. The woman walked off angrily and decided to punish him the next day. The next morning she came back in a fur coat, with a purse in one hand and a long umbrella in the other. This time the clerk didn''t recognize her and was eager to serve her. He climbed into the window to take the dress off the display. As soon as she saw it, she said she didn''t like it. She made the clerk bring almost everything in the window, one thing after another. Then, with a smile, she finally bought the very dress she had asked for the first time.","explanation_cn":"课文说 This time the clerk didn''t recognize her and was eager to serve her,没认出她才热情。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
